@dataclass
class FssaiHygieneAuditsEntity21:
    """Data transfer object for FSSAI Food Safety Compliance Checklist and Audit Logger - Segment 21."""
    entity_id: str = field(default_factory=lambda: str(uuid.uuid4()))
    restaurant_code: str = "REST-IND-001"
